property.value:
let $root := function($node) {
  let $statement := $node/ancestor::*[self::ExpressionStatement or self::ReturnStatement or self::LocalVariableDeclaration][last()],
      $chain := ($statement/VariableDeclarator/*[2], $statement/*[1])[1]
  return string(($chain/descendant-or-self::*[not(*)]
    [not(ancestor-or-self::*[exists(ancestor::*[. is $chain])][preceding-sibling::*])])[1]/@Name)
}
return (
  //MethodCall[@MethodName = 'csrf'][ArgumentList/LambdaExpression//MethodCall[@MethodName = 'disable']]
  | //MethodCall[@MethodName = 'csrf'][ArgumentList/MethodReference[@MethodName = 'disable']]
  | //MethodCall[@MethodName = 'disable'][*[1][self::MethodCall[@MethodName = 'csrf'][not(ArgumentList/*)]]]
)[let $chain := $root(.), $calls := ancestor::MethodDeclaration[1]//MethodCall[$root(.) = $chain]
  return not($calls[@MethodName = 'sessionCreationPolicy'][.//*[@Name = 'STATELESS']]
    or $calls[@MethodName = ('securityContext', 'securityContextRepository')][.//*[
      pmd-java:typeIs('org.springframework.security.web.context.NullSecurityContextRepository')
      or pmd-java:typeIs('org.springframework.security.web.server.context.NoOpServerSecurityContextRepository')]]
    or ($calls[@MethodName = 'oauth2ResourceServer'][.//(MethodCall | MethodReference)[@MethodName = ('jwt', 'opaqueToken')]]
        and not($calls[@MethodName = ('formLogin', 'httpBasic', 'rememberMe', 'oauth2Login', 'saml2Login')]
          [not(ArgumentList/MethodReference[@MethodName = 'disable']
            or ArgumentList/LambdaExpression[.//MethodCall[@MethodName = 'disable']]
            or parent::MethodCall[@MethodName = 'disable'])])))]
